package com.learnagent.demo;

import com.learnagent.course.*;import com.learnagent.quiz.*;import com.learnagent.task.*;import com.learnagent.weekly.*;import java.time.*;import java.util.*;import org.slf4j.*;import org.springframework.boot.*;import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;

@Component@Profile("demo")public class DemoDataInitializer implements ApplicationRunner{private static final Logger log=LoggerFactory.getLogger(DemoDataInitializer.class);private final CourseRepository courses;private final StudyTaskRepository tasks;private final QuizRepository quizzes;private final QuestionRepository questions;private final AnswerRecordRepository answers;private final WeeklyReviewRepository reviews;private final WeeklyReviewService weekly;private final Clock clock;public DemoDataInitializer(CourseRepository courses,StudyTaskRepository tasks,QuizRepository quizzes,QuestionRepository questions,AnswerRecordRepository answers,WeeklyReviewRepository reviews,WeeklyReviewService weekly,Clock clock){this.courses=courses;this.tasks=tasks;this.quizzes=quizzes;this.questions=questions;this.answers=answers;this.reviews=reviews;this.weekly=weekly;this.clock=clock;}@Override@Transactional public void run(ApplicationArguments args){Course os=course("Operating Systems","Processes, memory, file systems, permissions, and concurrency.");Course java=course("Java Programming","Object-oriented programming, collections, concurrency, and modern Java.");Course networks=course("Computer Networks","Network layers, TCP/IP, routing, and reliable transport.");task(os,"Review Linux file permissions","Practice owner, group, others, chmod and chown.",TaskPriority.HIGH,TaskStatus.TODO,1);task(os,"Summarize process scheduling","Create a one-page comparison of common schedulers.",TaskPriority.MEDIUM,TaskStatus.IN_PROGRESS,2);task(os,"Complete file-system notes","Review inode and directory structures.",TaskPriority.MEDIUM,TaskStatus.COMPLETED,-1);task(java,"Finish Java collections lab","Complete the map and stream exercises.",TaskPriority.HIGH,TaskStatus.TODO,3);task(java,"Review inheritance","Compare abstract classes and interfaces.",TaskPriority.LOW,TaskStatus.COMPLETED,-2);task(networks,"Practice subnetting","Solve five CIDR calculation questions.",TaskPriority.HIGH,TaskStatus.IN_PROGRESS,1);task(networks,"Review TCP reliability","Explain ACK, retransmission, and congestion control.",TaskPriority.MEDIUM,TaskStatus.TODO,4);task(networks,"Read transport lecture","Mark important concepts for review.",TaskPriority.LOW,TaskStatus.COMPLETED,-3);seedPermissionsQuiz(os);boolean meaningful=weekly.list().stream().anyMatch(review->review.statistics().tasksCompleted()>0||review.statistics().questionsAnswered()>0);if(!meaningful)weekly.generate();log.info("Demo profile ready: {} courses, {} tasks, {} quizzes, {} weekly reviews",courses.count(),tasks.count(),quizzes.count(),reviews.count());}private Course course(String name,String description){return courses.findByName(name).orElseGet(()->courses.save(new Course(name,description)));}private void task(Course course,String title,String description,TaskPriority priority,TaskStatus status,int dueOffset){if(tasks.existsByTitleAndCourseId(title,course.getId()))return;StudyTask task=new StudyTask(course.getId(),title,description,clock.instant().plus(Duration.ofDays(dueOffset)),priority);if(status==TaskStatus.COMPLETED)task.complete();else if(status==TaskStatus.IN_PROGRESS)task.update(title,description,task.getDueAt(),TaskStatus.IN_PROGRESS,priority);tasks.save(task);}private void seedPermissionsQuiz(Course course){if(quizzes.findByTitleAndCourseId("Linux Permissions Baseline",course.getId()).isPresent())return;Quiz quiz=quizzes.save(new Quiz(course.getId(),"Linux Permissions Baseline","Linux file permissions"));List<String> prompts=List.of("Which permission controls reading a file?","Which command changes file modes?","Who is represented by the middle permission triplet?","Which command changes file ownership?","What does chmod 640 grant to others?");List<String> correct=List.of("read","chmod","group","chown","no permissions");List<String> submitted=List.of("read","chmod","owner","chmod","read");for(int index=0;index<prompts.size();index++){String answer=correct.get(index);String options="[\""+answer+"\",\"write\",\"execute\",\"none\"]";Question question=questions.save(new Question(quiz.getId(),prompts.get(index),options,answer,"This question checks the owner/group/others permission model.","Linux file permissions"));answers.save(new AnswerRecord(quiz.getId(),question.getId(),course.getId(),"Linux file permissions",submitted.get(index),answer.equals(submitted.get(index))));}quiz.complete();quizzes.save(quiz);}}
